#include <stdio.h>
#include <string.h>
#include <thinkthen.h>

thinkthen_engine *tt = thinkthen_engine_new();

/* place 1 gives the refund deadline */
const char *find = "{\"find\": \"Which line gives the refund deadline?\", "
    "\"units\": [\"Returns need the original receipt.\", "
    "\"Refunds are issued within 30 days of purchase.\", "
    "\"Shipping is free on orders over $50.\", "
    "\"Gift cards cannot be exchanged for cash.\"]}";
char *found = thinkthen_call(tt, find);
puts(found ? found : thinkthen_error_message(tt));
thinkthen_free_string(found);
